package io.github.diodeme.ji.extension;

import io.github.diodeme.ji.ai.CancellationToken;
import java.util.Map;
import java.util.Objects;

/** Deterministic, source-attributed system-prompt contribution. */
public interface PromptContributor {
    ContributorId id();

    ResourceDescriptor.SourceId source();

    int priority();

    int tokenBudget();

    Contribution contribute(PromptContext context);

    record ContributorId(String value) {
        public ContributorId {
            if (value == null || value.isBlank()) throw new IllegalArgumentException("contributor id must not be blank");
        }
    }

    record PromptContext(String sessionId, String workspaceId, String locale, Map<String, String> variables,
                         CancellationToken cancellation) {
        public PromptContext {
            sessionId = requireText(sessionId, "sessionId");
            workspaceId = requireText(workspaceId, "workspaceId");
            locale = requireText(locale, "locale");
            variables = Map.copyOf(variables);
            Objects.requireNonNull(cancellation, "cancellation");
        }
    }

    record Contribution(String text) {
        public Contribution {
            Objects.requireNonNull(text, "text");
            text = text.trim();
        }
    }

    private static String requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
